<?php
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/functions.php';
require_once __DIR__.'/../includes/admin_crud_helpers.php';
require_role(['admin','guru','siswa']);
$isAdmin = (current_user()['role'] ?? '') === 'admin';
$errors = [];
$edit=null;if($isAdmin&&isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM galeri WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch(PDO::FETCH_ASSOC);}
if($isAdmin&&$_SERVER['REQUEST_METHOD']==='POST'){sg_verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){$q=$pdo->prepare('SELECT gambar FROM galeri WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn();$q=$pdo->prepare('DELETE FROM galeri WHERE id=?');$q->execute([$id]);if($old && !preg_match('~^https?://~i',$old)){ $p=realpath(__DIR__.'/../'.ltrim($old,'/'));$base=realpath(__DIR__.'/../assets/uploads/galeri');if($p&&$base&&str_starts_with($p,$base.DIRECTORY_SEPARATOR))@unlink($p);}sg_flash_redirect('Foto galeri berhasil dihapus.',BASE_URL.'/dashboard/galeri.php');}
$judul=trim($_POST['judul']??'');$deskripsi=trim($_POST['deskripsi']??'');$tanggal=$_POST['tanggal_dokumentasi']??'';$kategori=trim($_POST['kategori']??'Dokumentasi');$gambar='';if($action==='update'){$oldQ=$pdo->prepare('SELECT gambar FROM galeri WHERE id=?');$oldQ->execute([$id]);$gambar=(string)($oldQ->fetchColumn()?:'');}if($judul===''||!$tanggal||$kategori==='')$errors[]='Judul, tanggal dokumentasi, dan kategori wajib diisi.';
if(isset($_FILES['gambar'])&&$_FILES['gambar']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['gambar'];if($f['error']!==UPLOAD_ERR_OK)$errors[]='Upload gambar gagal.';elseif($f['size']>5*1024*1024)$errors[]='Ukuran gambar maksimal 5 MB.';else{$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime])||getimagesize($f['tmp_name'])===false)$errors[]='Format gambar harus JPG, PNG, atau WEBP.';else{$dir=__DIR__.'/../assets/uploads/galeri/';if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))$errors[]='Folder upload tidak dapat dibuat.';else{$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(move_uploaded_file($f['tmp_name'],$dir.$name))$gambar='assets/uploads/galeri/'.$name;else$errors[]='Gambar gagal disimpan.';}}}}
if($action!=='update' && $gambar==='')$errors[]='Pilih foto untuk galeri.';
if(!$errors){if($action==='update'){$q=$pdo->prepare('UPDATE galeri SET judul=?,deskripsi=?,gambar=?,tanggal_dokumentasi=?,kategori=? WHERE id=?');$q->execute([$judul,$deskripsi,$gambar,$tanggal,$kategori,$id]);}else{$q=$pdo->prepare('INSERT INTO galeri(judul,deskripsi,gambar,tanggal_dokumentasi,kategori) VALUES(?,?,?,?,?)');$q->execute([$judul,$deskripsi,$gambar,$tanggal,$kategori]);}sg_flash_redirect('Data galeri berhasil disimpan.',BASE_URL.'/dashboard/galeri.php');}$edit=['id'=>$id,'judul'=>$judul,'deskripsi'=>$deskripsi,'gambar'=>$gambar,'tanggal_dokumentasi'=>$tanggal,'kategori'=>$kategori];}
$cat=trim($_GET['kategori']??'');$cats=$pdo->query("SELECT DISTINCT kategori FROM galeri WHERE kategori IS NOT NULL AND kategori<>'' ORDER BY kategori")->fetchAll(PDO::FETCH_COLUMN);$sql='SELECT * FROM galeri';$params=[];if($cat!==''){$sql.=' WHERE kategori=?';$params[]=$cat;}$sql.=' ORDER BY tanggal_dokumentasi DESC,id DESC';$st=$pdo->prepare($sql);$st->execute($params);$photos=$st->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Galeri Kenangan — STEINS GATE';include __DIR__.'/../includes/dashboard_page_start.php';?>
<div class="page-heading"><div><div class="section-kicker">DIGITAL MEMORY ARCHIVE</div><h1>Galeri <em>Kenangan.</em></h1><p>Dokumentasi perjalanan dan momen kelas IPA 2.</p></div><?php if($isAdmin):?><a href="#form-galeri" class="btn btn-brown"><i class="bi bi-plus-lg me-1"></i>Tambah Foto</a><?php endif;?></div><?php sg_show_flash();foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?>
<?php if($isAdmin):?><div class="sg-panel mb-4" id="form-galeri"><h3><?=$edit?'Ubah Foto Galeri':'Tambah Foto Galeri'?></h3><form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="csrf_token" value="<?=e(sg_csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=e($edit['id'])?>"><?php endif;?><div class="col-md-6"><label class="form-label">Judul Foto</label><input name="judul" class="form-control custom-input" value="<?=e($edit['judul']??'')?>" required></div><div class="col-md-3"><label class="form-label">Tanggal Dokumentasi</label><input type="date" name="tanggal_dokumentasi" class="form-control custom-input" value="<?=e($edit['tanggal_dokumentasi']??date('Y-m-d'))?>" required></div><div class="col-md-3"><label class="form-label">Kategori</label><input name="kategori" class="form-control custom-input" value="<?=e($edit['kategori']??'Dokumentasi')?>" required></div><div class="col-12"><label class="form-label">Deskripsi</label><textarea name="deskripsi" rows="2" class="form-control custom-input"><?=e($edit['deskripsi']??'')?></textarea></div><div class="col-12"><label class="form-label">Foto (JPG/PNG/WEBP, maksimal 5 MB) <?=$edit?'— kosongkan jika tidak diganti':''?></label><input type="file" name="gambar" accept="image/jpeg,image/png,image/webp" class="form-control custom-input" <?=$edit?'':'required'?>></div><div class="col-12"><button class="btn btn-brown">Simpan</button> <?php if($edit):?><a class="btn btn-outline-secondary" href="<?=BASE_URL?>/dashboard/galeri.php">Batal</a><?php endif;?></div></form></div><?php endif;?>
<div class="sg-panel mb-3"><form method="get" class="row g-2"><div class="col-md-10"><select name="kategori" class="form-select custom-input"><option value="">Semua kategori</option><?php foreach($cats as $c):?><option value="<?=e($c)?>" <?=$cat===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="col-md-2 d-grid"><button class="btn btn-brown">Filter</button></div></form></div><div class="sg-gallery"><?php foreach($photos as $p):$src=trim($p['gambar']);$img=preg_match('~^https?://~i',$src)?$src:BASE_URL.'/'.ltrim($src,'/');?><article class="sg-gallery-item"><a href="<?=e($img)?>" target="_blank" rel="noopener"><img src="<?=e($img)?>" alt="<?=e($p['judul'])?>" loading="lazy"></a><div class="body"><span class="sg-meta"><?=e($p['kategori']??'Dokumentasi')?> · <?=date('d M Y',strtotime($p['tanggal_dokumentasi']))?></span><h3 class="mt-2 fs-6"><?=e($p['judul'])?></h3><p class="sg-meta"><?=e($p['deskripsi']??'')?></p><?php if($isAdmin):?><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-secondary" href="?edit=<?=$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Hapus foto ini?')"><input type="hidden" name="csrf_token" value="<?=e(sg_csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form></div><?php endif;?></div></article><?php endforeach;?></div><?php if(!$photos):?><div class="sg-panel text-center">Belum ada foto galeri.</div><?php endif;?><?php include __DIR__.'/../includes/dashboard_page_end.php';?>